// SPDX-License-Identifier: MIT
// Brand guard for Nodu · 见微 v2 (rules: brand/README.md, .kiro/steering/nodu-brand.md).
// Fails when:
// 1. A file generated by brand/scripts/build.cjs (SVG masters, brand/tokens.*, the IDE module
//    nodu-brand.ts) differs from what brand/src would generate now.
// 2. A token pair misses its WCAG target (4.5:1 text, 3:1 UI and large text).
// 3. Raster exports (PNG / ICO / ICNS) are missing or older than their SVG masters.
// 4. Desktop UI source (tracked files in scope-extension/src and style) still uses a superseded
//    v1 colour, or hardcodes a v2 brand colour instead of NODU_COLORS / --theia-* variables.
// 5. The Electron window background is not the dark editor token.
// Run from anywhere: node desktop/scripts/check-brand.cjs   (desktop: npm run check:brand)
'use strict';
const { execFileSync } = require('node:child_process');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const repo = path.resolve(__dirname, '..', '..');
const T = require(path.join(repo, 'brand/src/tokens.cjs'));
const { outputs } = require(path.join(repo, 'brand/scripts/build.cjs'));

const GENERATED_IDE = 'desktop/scope-extension/src/browser/nodu-brand.ts';
const failures = [];
const fail = (rule, message) => failures.push(`[${rule}] ${message}`);
const read = rel => fs.readFileSync(path.join(repo, rel), 'utf8');

// 1. Generated files are in sync with brand/src.
const generated = outputs();
for (const { path: rel, content } of generated) {
    const file = path.join(repo, rel);
    if (!fs.existsSync(file)) fail('generated', `${rel} is missing; run node brand/scripts/build.cjs`);
    else if (fs.readFileSync(file, 'utf8') !== content) fail('generated', `${rel} differs from brand/src; run node brand/scripts/build.cjs (never edit it by hand)`);
}

// 2. Contrast targets.
for (const theme of ['dark', 'light']) {
    for (const c of T.checks(theme).filter(c => !c.pass)) fail('contrast', `${theme}: ${c.label} is ${c.value}:1, needs ${c.min}:1`);
}

// 3. Rasters exist and were exported from the current SVG masters.
const assets = 'brand/assets';
const rasters = ['Nodu.icns', 'Nodu.ico', 'logo-on-light.png', 'logo-on-dark.png',
    ...[16, 24, 32, 48, 64, 128, 256, 512, 1024].map(s => `app-icon-${s}.png`),
    ...[16, 32, 128, 256, 512].flatMap(s => [`Nodu.iconset/icon_${s}x${s}.png`, `Nodu.iconset/icon_${s}x${s}@2x.png`])];
for (const rel of rasters) if (!fs.existsSync(path.join(repo, assets, rel))) fail('raster', `${assets}/${rel} is missing; run brand/scripts/rasterize.cjs`);
const manifest = path.join(repo, assets, 'raster-sources.json');
if (!fs.existsSync(manifest)) {
    fail('raster', `${assets}/raster-sources.json is missing; run brand/scripts/rasterize.cjs`);
} else {
    const recorded = JSON.parse(fs.readFileSync(manifest, 'utf8'));
    for (const [svg, hash] of Object.entries(recorded)) {
        const expected = generated.find(g => g.path === `${assets}/${svg}`);
        const current = expected && crypto.createHash('sha256').update(expected.content).digest('hex');
        if (current !== hash) fail('raster', `rasters from ${svg} are stale; run brand/scripts/rasterize.cjs after build.cjs`);
    }
}

// 4. Colour literals in desktop UI source (tracked files, working-tree content).
const hexes = list => new Set(list.map(h => h.toUpperCase()));
const legacy = hexes(T.legacy);
const brand = hexes([...Object.values(T.core).map(c => c.hex), ...T.blueRamp.map(([, h]) => h), ...T.yellowRamp.map(([, h]) => h)]);
const tracked = execFileSync('git', ['ls-files', '-z', '--cached', '--', 'desktop/scope-extension/src', 'desktop/scope-extension/style'], { cwd: repo, encoding: 'utf8' })
    .split('\0').filter(f => /\.(tsx?|css)$/.test(f) && f !== GENERATED_IDE);
let scanned = 0;
for (const rel of tracked) {
    let text;
    try { text = read(rel); } catch { continue; } // deleted in the working tree
    scanned++;
    text.split('\n').forEach((line, i) => {
        for (const match of line.matchAll(/#[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?\b/g)) {
            const hex = match[0].slice(0, 7).toUpperCase();
            if (legacy.has(hex)) fail('legacy', `${rel}:${i + 1} uses superseded v1 colour ${match[0]}`);
            else if (brand.has(hex)) fail('literal', `${rel}:${i + 1} hardcodes brand colour ${match[0]}; use NODU_COLORS or a --theia-* variable`);
        }
        if (/--theia-terminal-ansiBrightGreen/.test(line)) fail('semantic', `${rel}:${i + 1} borrows terminal green; use var(--theia-scope-ok)`);
    });
}

// 5. Electron window background.
const electron = JSON.parse(read('desktop/electron-app/package.json'));
const bg = electron.theia?.frontend?.config?.electron?.windowOptions?.backgroundColor;
if (!bg || bg.toUpperCase() !== T.resolve('dark').editor.toUpperCase()) {
    fail('window', `desktop/electron-app/package.json windowOptions.backgroundColor is ${bg}, expected ${T.resolve('dark').editor}`);
}

if (failures.length) {
    console.error(`check-brand failed (${failures.length}):`);
    for (const f of failures) console.error(`  ${f}`);
    process.exit(1);
}
console.log(`check-brand: brand v${T.version} — ${generated.length} generated files in sync, ` +
    `${T.checks('dark').length + T.checks('light').length} contrast pairs pass, ${rasters.length} rasters current, ${scanned} UI source files clean.`);
